+        assert!(matches!(result, Err(BivvyError::ConfigParseError { .. })));
+
+        let msg = result.unwrap_err().to_string();
+        assert!(msg.contains("ap_name"), "should list ap_name: {}", msg);
+        assert!(msg.contains("stepz"), "should list stepz: {}", msg);
+        assert!(
+            msg.contains("unknown_field"),
+            "should list unknown_field: {}",
+            msg
+        );
+    }
